class Student:
    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def average(self):
        return sum(self.marks) / len(self.marks)

student = Student("Amina", [84, 90, 78])
print(f"{student.name}: {student.average():.1f}")

